import { nextDelay } from './retry';

export async function relayFetch(url: string, init: RequestInit, attempt = 0): Promise<Response> {
  const res = await fetch(url, init);
  if (res.status >= 500 && attempt < 8) {
    await new Promise((r) => setTimeout(r, nextDelay(attempt)));
    return relayFetch(url, init, attempt + 1);
  }
  return res;
}

