export const MAX_ATTEMPTS = 5;
export async function nack(job: Job, opts: { delaySeconds: number }) {
  if (job.attempts >= MAX_ATTEMPTS) return deadLetter(job);
  return requeue(job, opts.delaySeconds);
}

